import React from "react";
import { Layout, Card, Select, Space} from "antd";
const { Option } = Select;

const CommonSider = ({selectedOptionOne, selectedOptionTwo, setSelectedOptionOne, setSelectedOptionTwo, eventList, EventClick}) => {
    return (
        <div className="menu" style={{ width: '100% '}}>
            <div direction="vertical" 
                size={4} 
                // align= "center"
                style={{ 
                    // position: 'absolute',
                    width: '100%',
                    zIndex: 10,
                    display: "flex",
                    justifyContent: "center"
               
            }}>
                <Select
                    value={selectedOptionOne}
                    onChange={setSelectedOptionOne}
                    
                    style={{ width: '100%', height: '3.5vh', marginTop: '8%'}}
                    >
                    <Option value="">All</Option> 
                    <Option value="Confusion">Confusion</Option>
                    <Option value="Trap">Trap</Option>
                    <Option value="Flitch">Flitch</Option>
                    <Option value="Poison">Poison</Option>
                    <Option value="Burn">Burn</Option>
                    <Option value="Sleep">Sleep</Option>
                    <Option value="Paralysis">Paralysis</Option>
                    <Option value="Freeze">Freeze</Option>
                </Select>
                <Select
                    value={selectedOptionTwo}
                    onChange={setSelectedOptionTwo}
                    
                    style={{ width: '100%', height: '3.5vh', marginTop: '8%'}}
                    >
                    <Option value="">All</Option> 
                    <Option value="Main Character">Main Character</Option>
                    <Option value="Rival">Rival</Option>
                    <Option value="Champion">Champion</Option>
                    <Option value="Gym Leader">Gym Leader</Option>
                </Select>
            </div>
            
            <ul className="event-list"
                style={{
                    height: '80%',
                    overflowY: 'auto',           
                    overflowX: 'hidden',         
                    scrollbarWidth: 'thin',      
                    scrollbarColor: '#c0c0c0 transparent', 

                    WebkitOverflowScrolling: 'touch',

                    padding: '0',  
                    margin: '0 auto',  
                    display: 'flex',  
                    flexDirection: 'column',  
                    alignItems: 'center',  
                    listStyle: 'none',  
                    width: '100%',  
                    marginTop: "5%"
                }}
            >
                {
                    eventList?.map(item => {
                        return (
                            <li style={{
                                overflow: "hidden",
                                cursor: 'pointer'
                                }}
                                onClick={() => EventClick(item.id)}                                   
                            >
                                <img src={`${process.env.PUBLIC_URL}${item.Icon}`} alt="eventIcon"
                                    style = {{
                                        width: '100%',
                                        height: 'auto',
                                        objectFit: 'cover',
                                        display: 'block',
                                        margin: '5px'
                                    }}
                                ></img>
                            </li>
                        )
                    })
                }
            </ul>
        </div>
    )
}


export default CommonSider;