import { Layout, Drawer, Button} from "antd";
import { MenuOutlined } from '@ant-design/icons';
import { Content } from "antd/es/layout/layout";
import React, { useState, useEffect } from "react";
import CommonSider from "../../components/commonSider";
import './index.css'


const Home =() => {
    const [pokemonData, setPokemonData] = useState([]);
    const [pairsList, setPairsList] = useState([]);
    const [curPairsList, setCurPairsList] = useState([])

    const [eventList, setEventList] = useState([])
    const [selectedOptionOne, setSelectedOptionOne] = useState('All');
    const [selectedOptionTwo, setSelectedOptionTwo] = useState('All');

    const [currentType, setcurrentType] = useState([])

    const [drawerVisible, setDrawerVisible] = useState(false)

    useEffect(() => {
        const fetchPokemonData = async () => {
            try {
                const response = await fetch(`${process.env.PUBLIC_URL}/data/sync_pairs.json`);
                const data = await response.json();
                setPokemonData(data);
                setPairsList(data)
                setCurPairsList(data)
            } catch (error) {
                console.error('读取拍组失败:', error);
            }
        };

        const fetchEventData = async () => {
            try {
                const response = await fetch(`${process.env.PUBLIC_URL}/data/events.json`);
                const data = await response.json()
                setEventList(data)
            } catch (error) {
                console.error('读取活动失败:', error)
            }
        }

        fetchPokemonData();
        fetchEventData();
    }, []);
    
    // console.log(pokemonData)
    
    useEffect(() => {
        console.log(pairsList)
        setCurPairsList(pairsList.filter(item => (item[selectedOptionOne] === true || selectedOptionOne === '') 
            && (item['Label'].some(i => i === selectedOptionTwo) || selectedOptionTwo === '')))
    }, [selectedOptionOne, selectedOptionTwo])

    const EventClick = (id) => {
        setcurrentType(eventList.find(item => item.id === id).Type)
    }

    useEffect(() => {
        setSelectedOptionOne('')
        setSelectedOptionTwo('')
        
        let Type1 = currentType[0]
        let Type2 = currentType[1]
        console.log(Type1 + " " + Type2)
        const filterList = pokemonData.filter(item => (item.Type === Type1 || item.Type === Type2))
        setPairsList(filterList)
        setCurPairsList(filterList)
        console.log(curPairsList)
    }, [currentType])
    
    return (
        <Layout>
            <Content className="homepage" 
                style={{ 
                    background: `url(${process.env.PUBLIC_URL}/background.png) repeat`,
                    backgroundSize: 'auto', 
                    backgroundPosition: 'center',
                    height: '90vh',
                    width: '100vw',
                    margin: '0px',
                    // position: 'relative'
                    display: "flex",
                    justifyContent: "center",
                }}
            > 
                <div className="sider-pc"
                    style={{
                    width: '20%',
                    alignSelf: 'flex-start'
                }}>
                    <CommonSider 
                        selectedOptionOne = {selectedOptionOne}
                        selectedOptionTwo = {selectedOptionTwo}
                        setSelectedOptionOne = {setSelectedOptionOne}
                        setSelectedOptionTwo = {setSelectedOptionTwo}
                        eventList = {eventList}
                        EventClick = {EventClick}
                    />
                </div>

                <div className="sider-button-mobile">
                    <Button 
                        icon={<MenuOutlined />} 
                        onClick={() => setDrawerVisible(true)}
                        className="menu-button"
                        ></Button>
                </div>

                <Drawer className="sider-mobile"
                    onClose={() => setDrawerVisible(false)}
                    open={drawerVisible}
                >
                    <CommonSider 
                        selectedOptionOne = {selectedOptionOne}
                        selectedOptionTwo = {selectedOptionTwo}
                        setSelectedOptionOne = {setSelectedOptionOne}
                        setSelectedOptionTwo = {setSelectedOptionTwo}
                        eventList = {eventList}
                        EventClick = {EventClick}
                    />
                </Drawer>
                
                
                <div className="container-box"
                    style = {{
                        // width: '75%',
                        flex: 1,
                        height: '90%',
                        boxSizing: 'border-box',
                        backgroundColor: 'rgba(58, 169, 255, 0.3)',
                        // position: 'absolute',
                        marginLeft: '2vw',
                        mariginRight: '2vw',
                        marginBottom: '1vh',
                        borderRadius: '30px',
                        overflowY: 'auto',
                        alignSelf: 'center'
                    }}>
                    <div style={{
                        display: 'grid',
                    
                        gridTemplateColumns: 'repeat(auto-fill, minmax(100px, 1fr))',
                        
                        // gridTemplateRows: 'repeat(5, 100px)',   // 5行，每行100px
                        gap: '1vw',
                        padding: '2%'
                    }}>
                        {
                            curPairsList.map(item => {
                                return ( 
                                <div
                                    key={item.id}
                                    style={{
                                        display: 'flex',
                                        alignItems: 'center',
                                        justifyContent: 'center',
                                        boxSizing: 'border-box',
                                        maxWidth: "100px",
                                    }}
                                    
                                    >
                                        <img src={`${process.env.PUBLIC_URL}${item.Icon}`} alt='icon' style={{
                                            width: '120%',    
                                            height: '120%',
                                            objectFit: 'contain', 
                                        }}></img>
                                </div>)
                            })
                        }
                    </div>
                </div>
                
                
                
            </Content>
        </Layout>
        
        
    )
}

export default Home;